zeScaleLK, lkp_61.FISCALWEEKNUM AS WEEKONFLOOR_LK, lkp_62.desc_1_douane AS TariffNoLK, lkp_63.DESC_1 AS BINFAMLYLK, lkp_65.desc_1 AS WARRGRPLK, lkp_66.LDESC_1 AS NHG15LK, lkp_67.LDESC_1 AS NHG16LK, lkp_68.Desc_1 AS Objective_ID_LK, lkp_69.LDESC_1 AS NHG17LK, lkp_70.LDESC_1 AS NHG18LK, lkp_71.Bom_template_desc AS VBOM_LK, lkp_72.LDESC_1 AS NHG19LK, lkp_73.LDESC_1 AS NHG20LK, lkp_74.metalid AS Metalid_LK, lkp_75.LDESC_1 AS NHG21LK, lkp_76.LDESC_1 AS NHG22LK, lkp_77.LDESC_1 AS NHG23LK, lkp_78.LDESC_1 AS NHG24LK, lkp_79.LDESC_1 AS NHG25LK, lkp_80.id AS MISC_FEELKUP
FROM INVENTORYMASTER a
left join SUPPLIERACCOUNTING b on (suppid=a.defsuppid)
left join invcolorext c on (c.productid=a.productid and c.dim1=a.nhg1)
left join pclass pc on  (pc.pclass=a.pclass)
left join psubc psc on psc.pclass=a.pclass and psc.psclass=a.psclass
left join pricing pk on (pk.pricekey=a.PRODUCTID and 
pk.pricezoneid='00' and pk.dim1='------' and
pk.efdatestart<='today' and pk.efdateends>='today')
left join suppprod e on e.productid=a.productid and e.suppid=a.defsuppid

/* Oct 7 2014    */  
left join prod_dev_steps pds on pds.cstep=a.dev_state

LEFT JOIN PRODGRPBMKS lkp_0 ON lkp_0.BMKS = a.BMKS LEFT JOIN COORDINATEGRP lkp_2 ON lkp_2.coordinategrp = a.COORDINATEGRP LEFT JOIN COSTMETHODS lkp_4 ON lkp_4.COSTMTHD = a.COSTMTHD LEFT JOIN DEPARTEMENTS lkp_7 ON lkp_7.DEPT = a.DEPT LEFT JOIN DIMENSIONS lkp_8 ON lkp_8.DIMENSIONID = a.DIMENSIONID LEFT JOIN HGDESCS lkp_9 ON lkp_9.hgs = a.HG1 AND lkp_9.hgs<>'-894728' LEFT JOIN HGDESCS lkp_10 ON lkp_10.hgs = a.HG2 AND lkp_10.hgs<>'-894728' LEFT JOIN HGDESCS lkp_11 ON lkp_11.hgs = a.HG3 AND lkp_11.hgs<>'-894728' LEFT JOIN HGDESCS lkp_13 ON lkp_13.hgs = a.HG4 AND lkp_13.hgs<>'-894728' LEFT JOIN HGDESCS lkp_14 ON lkp_14.hgs = a.HG5 AND lkp_14.hgs<>'-894728' LEFT JOIN HGDESCS lkp_15 ON lkp_15.hgs = a.HG6 AND lkp_15.hgs<>'-894728' LEFT JOIN INVCONTROLMETHOD lkp_16 ON lkp_16.INVCONTRLMTHD = a.INVCONTRLMTHD LEFT JOIN POMADDCOSTFORMULAS lkp_17 ON lkp_17.PACFORMULA = a.PACFORMULA LEFT JOIN PCLASS lkp_18 ON lkp_18.PCLASS = a.PCLASS LEFT JOIN PSUBC lkp_19 ON lkp_19.pclass = a.PCLASS AND lkp_19.PSCLASS = a.PSCLASS LEFT JOIN SEASONS lkp_20 ON lkp_20.SEASONID = a.SEASONID LEFT JOIN SEASONS lkp_21 ON lkp_21.SEASONID = a.SEASONID LEFT JOIN TICKETFORMATS lkp_22 ON lkp_22.TICKETFORMAT = a.TICKETFORMAT LEFT JOIN UNITSOFMESURE lkp_23 ON lkp_23.UNITOFMESURE = a.UNITOFMESURE LEFT JOIN WARRPERIODS lkp_24 ON lkp_24.WCODE = a.WCODE LEFT JOIN DIMSELECLASS lkp_25 ON lkp_25.ELECLASS = a.eleclass1 LEFT JOIN DIMSELECLASS lkp_26 ON lkp_26.ELECLASS = a.eleclass2 LEFT JOIN DIMSELECLASS lkp_27 ON lkp_27.ELECLASS = a.eleclass3 LEFT JOIN ELEMENTS lkp_28 ON lkp_28.ELEMENTID = a.NHG1 AND lkp_28.ELECLASS='NHG' AND lkp_28.elementorder=1 LEFT JOIN ELEMENTS lkp_30 ON lkp_30.ELEMENTID = a.NHG2 AND lkp_30.ELECLASS='NHG' AND lkp_30.elementorder=2 LEFT JOIN ELEMENTS lkp_31 ON lkp_31.ELEMENTID = a.NHG3 AND lkp_31.ELECLASS='NHG' AND lkp_31.elementorder=3 LEFT JOIN ELEMENTS lkp_32 ON lkp_32.ELEMENTID = a.NHG4 AND lkp_32.ELECLASS='NHG' AND lkp_32.elementorder=4 LEFT JOIN ELEMENTS lkp_33 ON lkp_33.ELEMENTID = a.NHG5 AND